CREATE TABLE IF NOT EXISTS "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text NOT NULL UNIQUE, "display_name" text, "avatar_url" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "auth_accounts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "provider" text NOT NULL, "provider_account_id" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "auth_provider_account_unique" ON "auth_accounts" ("provider", "provider_account_id");
CREATE TABLE IF NOT EXISTS "projects" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_user_id" uuid REFERENCES "users"("id") ON DELETE CASCADE, "guest_session_id" text, "name" text NOT NULL, "slug" text NOT NULL, "framework" text, "source_type" text NOT NULL DEFAULT 'zip', "source_reference" text, "root_directory" text NOT NULL DEFAULT '/', "build_command" text, "output_directory" text, "status" text NOT NULL DEFAULT 'uploaded', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "deleted_at" timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS "projects_slug_unique" ON "projects" ("slug");
CREATE INDEX IF NOT EXISTS "projects_owner_idx" ON "projects" ("owner_user_id");
CREATE INDEX IF NOT EXISTS "projects_created_idx" ON "projects" ("created_at");
CREATE TABLE IF NOT EXISTS "deployments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE, "provider" text NOT NULL DEFAULT 'vercel', "provider_project_id" text, "provider_deployment_id" text, "status" text NOT NULL DEFAULT 'queued', "deployment_url" text, "commit_reference" text, "error_code" text, "started_at" timestamptz, "finished_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "deployments_project_idx" ON "deployments" ("project_id");
CREATE TABLE IF NOT EXISTS "domains" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE, "hostname" text NOT NULL, "provider_domain_id" text, "status" text NOT NULL DEFAULT 'pending', "https_status" text NOT NULL DEFAULT 'unknown', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "domains_hostname_unique" ON "domains" ("hostname");
CREATE INDEX IF NOT EXISTS "domains_project_idx" ON "domains" ("project_id");
CREATE TABLE IF NOT EXISTS "project_settings" ("project_id" uuid PRIMARY KEY REFERENCES "projects"("id") ON DELETE CASCADE, "package_manager" text NOT NULL DEFAULT 'npm', "install_command" text, "build_command" text, "output_directory" text, "root_directory" text NOT NULL DEFAULT '/', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "usage_records" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_user_id" uuid REFERENCES "users"("id") ON DELETE CASCADE, "guest_session_id" text, "project_id" uuid REFERENCES "projects"("id") ON DELETE CASCADE, "event_type" text NOT NULL, "quantity" integer NOT NULL DEFAULT 1, "period_start" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "usage_records_project_idx" ON "usage_records" ("project_id");
CREATE TABLE IF NOT EXISTS "github_installations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "provider_installation_id" text NOT NULL UNIQUE, "status" text NOT NULL DEFAULT 'active', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "job_type" text NOT NULL, "project_id" uuid REFERENCES "projects"("id") ON DELETE CASCADE, "deployment_id" uuid REFERENCES "deployments"("id") ON DELETE CASCADE, "status" text NOT NULL DEFAULT 'queued', "attempt_count" integer NOT NULL DEFAULT 0, "scheduled_at" timestamptz NOT NULL DEFAULT now(), "started_at" timestamptz, "finished_at" timestamptz, "last_error_code" text, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "jobs_status_idx" ON "jobs" ("status", "scheduled_at");
